  /* ===================================================================
     1. CONFIG — the knobs a new game changes first.
     =================================================================== */
  var CONFIG = {
    title:   "Stratideck",
    /* One sentence, three words in colour: the gesture, what it lands on and
       the one rule that decides a fight. The stage under it drags a blue card
       onto a face-down red one, which flips and falls. */
    tagline: "<b class=\"w-drag\">Drag</b> a card onto a <b class=\"w-hidden\">hidden</b> enemy, the higher <b class=\"w-rank\">rank</b> wins",
    /* NO CLOCK. A battle is turn-based: it ends when the enemy camp is empty,
       its flag is taken, or the player's army is spent. */
    gameSeconds: 0,

    // Store links used by every CTA. Until this game has a real listing all
    // three point at the newrare site, where the game can actually be played.
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },

    designWidth: 720,
    designHeight: 1280,
    bg: "#0a1026",

    /* The painted camp goes behind the ROUND too: the grid, the hand and the
       readouts are drawn over the band's own scene, on a translucent panel,
       so the round is played in the world the level map shows. render()
       asks Art.scene() before painting a ground of its own. */
    sceneArt: true,

    layout: { hudHeight: 150, ctaHeight: 112, sideMargin: 26 },

    // The stage is the drag variant, re-dressed from the SKIN as a battle
    // grid: the shared finger carries a blue card up onto a face-down red one.
    intro: { logo: null, demo: "drag", caption: "" },

    // SPACE starts and replays; a grid pick is a pointer's job.
    keyboard: true,

    // The centre score is always there; the right slot counts the foes.
    hud: { score: true, timer: false },

    /* THE BED. One track, six windows of it: five for the bands of the climb
       (below) and a quiet, slower one under the menus. The entry points are
       the track's own seams, measured (docs/MUSIC.md): a quiet intro to 30 s,
       the body from 30, a full section 45-75, a break at 75, a second body
       80-110, a breakdown 115-125, the loudest section 125-155, an outro to
       170 and the fade from 173. */
    music: {
      volume: 0.11, fade: 1.8,
      menu: { from: 0, length: 30, rate: 0.85, gain: 0.5 }
    },
    /* THE FIVE BANDS OF THE CLIMB, six levels apiece — the same stretches the
       level map names on its card. Each carries the PICTURE the round and the
       end screen are played over and the STRETCH of the track under it, so the
       two can only turn over together. `scene` is a key of CONFIG.art, injected
       out of assets/image/embed/stratideck-background-phone-NN.webp. A playable
       is one round at level 0: it rides the first band, the only scene and the
       only window the builder embeds in it. */
    bands: [
      { scene: "backgroundPhone01", music: { from: 30,  length: 30 } },  //  1-6   Outpost
      { scene: "backgroundPhone02", music: { from: 45,  length: 30 } },  //  7-12  Palisade
      { scene: "backgroundPhone03", music: { from: 80,  length: 30 } },  // 13-18  Warcamp
      { scene: "backgroundPhone04", music: { from: 125, length: 30 } },  // 19-24  Siege
      { scene: "backgroundPhone05", music: { from: 140, length: 30 } }   // 25-30  Citadel
    ],

    // All user-facing copy in one place.
    copy: {
      start:      "To battle",
      ctaBar:     "Install now",
      ctaEnd:     "Play the full game",
      replay:     "Fight again",
      scoreLabel: "Score",
      timeLabel:  "Time",
      endScore:   "Final score",
      gameOver:   "Army lost",
      timeUp:     "Time's up!",
      victory:    "Camp taken!",
      flagTaken:  "Flag captured!",
      cardsLabel: "Cards",
      foesLabel:  "Foes"
    },

    /* --- game tunables ------------------------------------------------
       The level layer lerps the ones its manifest names (web.levels.tune)
       between level 1 and level 30, in place; section 6 re-reads them on
       every reset, so a playable reads the same numbers it always did. */
    play: {
      cols: 4,           // the enemy camp: columns...
      rows: 3,           // ...and rows of face-down cards
      traps: 0,          // traps hidden in the camp (only a sapper clears one)
      deckRatio: 1.1,    // the player's army, as a share of the camp's cells
      enemyBias: -1.0,   // shift on the enemy ranks drawn: negative = weaker camp
      deckBias: 0.6,     // the same shift on the player's own army
      handSize: 4,       // cards on the table at once
      goal: 900,         // the playable's own objective: 1 star at it, 2 at 1.5x, 3 at 2.2x
      cornerClear: 96    // the hand stops this far above the frame's foot, so the
                         // web target's two corner pills never cover a card
    }
  };

  /* ===================================================================
     2. ASSETS — embedded base64 data URIs only (no network requests ever).
     =================================================================== */
  var ASSETS = {
    /* No `logo`: this game ships a painted logotype
       (assets/image/master/stratideck-title.png) and the shell hides
       #app-icon as soon as one exists. The card crests, the special ranks,
       the flag, the trap and the decor pool are painted too — cut out of
       stratideck-object-other.png and named in art.objects of the manifest
       (piece-01..09, decor-01..04). */
    images: {},
    sounds: {
      // The background bed, looped and crossfaded by Music. The playable's cut
      // is the FIRST band's window and nothing else; the web target ships the
      // whole track instead (`web.music` in the manifest):
      //   ffmpeg -ss 30 -t 30 -i assets/audio/music/stratideck.mp3 -ac 1 -ar 44100 -b:a 64k music.mp3
      // assets/audio/sfx/*.mp3, trimmed and re-encoded mono 32 kHz / 64 kbps
      // pick:    ui_tone_short_thin_clicky_positive_correct_92811       (a hand card is picked up)
      // place:   ui_percussive_sent_99574                               (it is sent at a cell)
      // flip:    ui_percussive_clicks_002_99573                         (the enemy card turns over)
      // clash:   sfx_hit_01_sport                                       (the two cards meet)
      // win:     gameshow_correct_answer_ping_ring_chime_006_92779      (the enemy falls)
      // lose:    game_sound_mallets_negative_error_002_70232            (the player's card falls)
      // tie:     sfx_hitwall_sport_01                                   (both fall)
      // trap:    ui_app_tone_delete_close_loud_001_91298                (a trap goes off)
      // flag:    alert_musical_harp_roll_completed_finished_109556      (the flag is taken)
      // victory: alert_ui_software_game_success_completed_finished_113741 (the camp is empty)
      // defeat:  notification_alert_layered_warm_negative_006_53900     (the army is spent)
      // warn:    alert_prompt_mallet_marimba_warning_subtle_104797      (last cards)
      pick: "data:audio/mpeg;base64,",
      place: "data:audio/mpeg;base64,",
      flip: "data:audio/mpeg;base64,",
      clash: "data:audio/mpeg;base64,",
      win: "data:audio/mpeg;base64,",
      lose: "data:audio/mpeg;base64,",
      tie: "data:audio/mpeg;base64,",
      trap: "data:audio/mpeg;base64,",
      flag: "data:audio/mpeg;base64,",
      victory: "data:audio/mpeg;base64,",
      defeat: "data:audio/mpeg;base64,",
      warn: "data:audio/mpeg;base64,",
      music: "data:audio/mpeg;base64,",
      // End-screen cues, shared by every game (played through Sound.cue, so a
      // game that drops them falls back to the synthesized beeps).
      // uiScore: alert_ping_chime_correct_answer_check_positive_009
      // uiStar:  alert_mallet_chime_ring_notification_002  (pitched per star)
      // uiRow:   alert_menu_select_item_beep_click_003
      uiScore: "data:audio/mpeg;base64,",
      uiStar: "data:audio/mpeg;base64,",
      uiRow: "data:audio/mpeg;base64,"
    }
  };

  /* ===================================================================
     6. GAME — STRATIDECK
     A camp of face-down enemy cards on a grid, and the player's own army
     dealt four at a time under it. A card is dragged (or tapped, then the
     cell tapped) onto an enemy the player can REACH — the bottom row at
     first, then whatever stands next to a cell already emptied, so the camp
     is opened corridor by corridor. The enemy turns over and the ranks
     decide: the higher one wins, equal ranks both fall, and three specials
     bend the rule the way Stratego does — the SPY kills the Marshal, the
     SAPPER is the only card that clears a TRAP, and the SCOUT does not fight
     at all: it reveals the card it is sent at and comes back. A card that
     wins returns to the bottom of the deck; a card that loses is gone. The
     enemy FLAG, once found, ends the battle in a capture. The camp grows
     with the level, and a level's camp is always the same, so a second try
     is played with what the first one learned.
     =================================================================== */
  var Game = (function () {
    var P = CONFIG.play;

    /* --- the ranks ------------------------------------------------------
       `art` is a painted cut of the object sheet (CONFIG.art.pieceNN, adopted
       in the manifest) for the ranks that have a face of their own; the
       others show their number. 11 and 12 are the two enemy-only cards. */
    var RANKS = {
      1:  { name: "Spy",        art: "piece08" },
      2:  { name: "Scout",      art: "piece07" },
      3:  { name: "Sapper",     art: "piece09" },
      4:  { name: "Sergeant" },
      5:  { name: "Lieutenant" },
      6:  { name: "Captain" },
      7:  { name: "Major" },
      8:  { name: "Colonel" },
      9:  { name: "General",    art: "piece06" },
      10: { name: "Marshal",    art: "piece05" },
      11: { name: "Trap",       art: "piece04" },
      12: { name: "Flag",       art: "piece03" }
    };
    var SPY = 1, SCOUT = 2, SAPPER = 3, GENERAL = 9, MARSHAL = 10, TRAP = 11, FLAG = 12;
    var CREST = { blue: "piece01", red: "piece02" };

    /* --- what a fight pays ------------------------------------------------
       A kill pays by the rank it took down, times how TIGHT the card was: the
       tightest card that could do it (one rank above, the spy on the marshal,
       the sapper on a trap) pays double, two ranks above pays even, and an
       OVERKILL — three or more — pays half. That margin is the whole economy
       of the game: a marshal thrown blind at the camp wins almost every fight
       and earns almost nothing, so a reveal is worth points on its own. The
       bench said so in one run — a pilot that only ever played its biggest
       card out-scored a careful one four to one on a flat payout. A streak
       of wins multiplies all of it, gently. */
    var KILL = 10, TIE = 10, TRAP_CLEAR = 120, SCOUT_PAY = 15;
    var FLAG_PAY = 300, ROUTED = 30, SURVIVOR = 30, STREAK_STEP = 0.2, STREAK_CAP = 2;

    /* --- colours ----------------------------------------------------------- */
    var GOLD = "#f2c14e", BLUE = "#5aa9ff", RED = "#ff5c5c", INK = "#f6f1e4";

    /* --- geometry (design px), rebuilt by geometry() ---------------------- */
    var G = {};
    var HAND_W = 118, HAND_H = 150, HAND_GAP = 14;

    /* --- state --------------------------------------------------------------- */
    var grid, cols, rows, deck, hand, handSize;
    var score, streak, bestStreak, kills, ties, losses, precise, scouted, trapsCleared;
    var reach, targets, selected, drag, turn, refills, mood, lastFoe, lastWon;
    var levelD, target, ended, outcome, tAnim, seed, BAND, flagCell;

    /* --- the level ------------------------------------------------------------
       The web target's level layer hands `d` (0 at the foot of the climb, 1
       at the top) before the round starts, and null for an endless run. The
       objective is the same number the map writes on its card — one lerp
       over web.levels.objective. A playable never gets the call and plays to
       its own goal. */
    function applyLevel(d) { levelD = (d == null) ? null : d; }
    function goalOf() {
      var L = CONFIG.web && CONFIG.web.levels && CONFIG.web.levels.objective;
      if (levelD == null || !L) return P.goal;
      var step = L.step || 1, v = L.from + (L.to - L.from) * levelD;
      return Math.round(v / step) * step;
    }
    function bandFor() {
      var b = CONFIG.bands;
      if (!CONFIG.level) return b[0];
      return b[clamp(Math.floor((CONFIG.level - 1) / 6), 0, b.length - 1)];
    }

    /* A tiny LCG for what has to be the same every time a level is opened:
       the camp and the deck. A level is a puzzle the player learns, so it is
       seeded by the level number; the playable and the endless run draw from
       Rand instead. */
    function lcg() {
      seed = (seed * 1664525 + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    function draw() { return CONFIG.level ? lcg() : Math.random(); }
    function drawInt(n) { return Math.min(n - 1, Math.floor(draw() * n)); }
    function shuffle(a) {
      for (var i = a.length - 1; i > 0; i--) {
        var j = Math.floor(draw() * (i + 1)), t = a[i]; a[i] = a[j]; a[j] = t;
      }
      return a;
    }

    /* --- helpers ------------------------------------------------------------- */
    function font(size, weight) {
      return (weight || 900) + " " + Math.round(size) + "px -apple-system,Segoe UI,Roboto,sans-serif";
    }
    function roundRect(g, x, y, w, h, r) {
      g.beginPath();
      g.moveTo(x + r, y);
      g.arcTo(x + w, y, x + w, y + h, r);
      g.arcTo(x + w, y + h, x, y + h, r);
      g.arcTo(x, y + h, x, y, r);
      g.arcTo(x, y, x + w, y, r);
      g.closePath();
    }
    function ease(t) { return 1 - (1 - t) * (1 - t) * (1 - t); }
    function art(key) {
      var img = ArtImages[key];
      return img && img.complete && img.naturalWidth ? img : null;
    }
    function rankName(r) { return RANKS[r].name; }

    /* ===================================================================
       THE CAMP AND THE ARMY
       =================================================================== */

    /* A weighted rank for a soldier: a pyramid over 2..10 (an enemy never
       needs a spy — it never attacks) leaned by `bias`, positive toward the
       high ranks. The player's own soldiers come off the same table. */
    function soldierRank(bias, min) {
      var w = { 2: 1.4, 3: 2.0, 4: 2.6, 5: 2.6, 6: 2.1, 7: 1.5, 8: 1.0, 9: 0.35, 10: 0.15 };
      var total = 0, r, x;
      for (r = min; r <= 10; r++) total += w[r] * Math.exp(bias * (r - 5) / 3);
      x = draw() * total;
      for (r = min; r <= 10; r++) {
        x -= w[r] * Math.exp(bias * (r - 5) / 3);
        if (x <= 0) return r;
      }
      return min;
    }

    /* The camp: a flag on the top row, the traps around it, one marshal and
       one general somewhere, soldiers everywhere else. `known` is what the
       player has seen of a cell; a defeated cell is null. */
    function buildGrid() {
      var r, c, cells = [], i;
      grid = [];
      for (r = 0; r < rows; r++) {
        grid.push([]);
        for (c = 0; c < cols; c++) { grid[r].push(null); cells.push({ r: r, c: c }); }
      }
      var fc = drawInt(cols);
      flagCell = { r: 0, c: fc };
      grid[0][fc] = { rank: FLAG, known: false, hurt: 0 };

      // the traps guard the flag first, then hide anywhere
      var around = [{ r: 0, c: fc - 1 }, { r: 0, c: fc + 1 }, { r: 1, c: fc }];
      var traps = P.traps | 0, placed = 0;
      shuffle(around);
      for (i = 0; i < around.length && placed < traps; i++) {
        var a = around[i];
        if (a.c < 0 || a.c >= cols || a.r >= rows || grid[a.r][a.c]) continue;
        grid[a.r][a.c] = { rank: TRAP, known: false, hurt: 0 }; placed++;
      }
      shuffle(cells);
      for (i = 0; i < cells.length && placed < traps; i++) {
        var q = cells[i];
        if (grid[q.r][q.c] || q.r === rows - 1) continue;   // never on the front row
        grid[q.r][q.c] = { rank: TRAP, known: false, hurt: 0 }; placed++;
      }
      // the soldiers, the two officers among them
      var free = [];
      for (i = 0; i < cells.length; i++) if (!grid[cells[i].r][cells[i].c]) free.push(cells[i]);
      var ranks = [];
      if (free.length >= 6) ranks.push(MARSHAL);
      if (free.length >= 8) ranks.push(GENERAL);
      while (ranks.length < free.length) ranks.push(soldierRank(P.enemyBias, 2));
      shuffle(ranks);
      for (i = 0; i < free.length; i++) grid[free[i].r][free[i].c] = { rank: ranks[i], known: false, hurt: 0 };
    }

    /* The army: one marshal, one general, one spy, the scouts, a sapper per
       trap (and one at least), soldiers to make the count. */
    function buildDeck() {
      var n = Math.max(6, Math.round(cols * rows * P.deckRatio)), i;
      var traps = P.traps | 0;
      deck = [MARSHAL, GENERAL, SPY, SCOUT, SCOUT];
      if (n >= 20) deck.push(SCOUT);
      var sappers = Math.max(1, traps + (traps >= 3 ? 1 : 0));
      for (i = 0; i < sappers; i++) deck.push(SAPPER);
      while (deck.length < n) deck.push(soldierRank(P.deckBias, 4));
      shuffle(deck);
      hand = [];
      refillHand(false);
    }

    function refillHand(animate) {
      var i;
      for (i = 0; i < handSize; i++) {
        if (hand[i] == null && deck.length) {
          hand[i] = deck.shift();
          if (animate) refills.push({ slot: i, t: 0 });
        }
      }
    }
    function countHand() {
      var n = 0;
      for (var i = 0; i < handSize; i++) if (hand[i] != null) n++;
      return n;
    }
    function cardsLeft() { return deck.length + countHand(); }
    function foesLeft() {
      var n = 0;
      for (var r = 0; r < rows; r++) for (var c = 0; c < cols; c++)
        if (grid[r][c] && grid[r][c].rank !== TRAP) n++;
      return n;
    }

    /* ===================================================================
       REACH — where the army can strike from
       A walk from a virtual row under the camp through the cells already
       emptied, four-way; every enemy standing next to a reached cell is a
       target. The front row is reachable from the start.
       =================================================================== */
    function computeReach() {
      var r, c, i, q = [], seen = {}, k;
      reach = {}; targets = {};
      for (c = 0; c < cols; c++) q.push({ r: rows, c: c });
      var dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
      while (q.length) {
        var p = q.shift();
        for (i = 0; i < 4; i++) {
          var nr = p.r + dirs[i][0], nc = p.c + dirs[i][1];
          if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
          k = nr + "," + nc;
          if (seen[k]) continue;
          if (grid[nr][nc] === null) { seen[k] = true; reach[k] = true; q.push({ r: nr, c: nc }); }
          else targets[k] = true;
        }
      }
    }
    function isTarget(r, c) { return !!targets[r + "," + c]; }
    function anyTarget() { for (var k in targets) if (targets.hasOwnProperty(k)) return true; return false; }

    /* ===================================================================
       GEOMETRY — everything derives from Layout
       =================================================================== */
    function geometry() {
      var bottom = Math.min(Layout.bottom, CONFIG.designHeight - P.cornerClear);
      G.handBottom = bottom;
      G.handY = bottom - HAND_H;
      var row = handSize * HAND_W + (handSize - 1) * HAND_GAP;
      G.handX0 = Layout.cx - row / 2;

      G.infoH = 168;
      G.infoY = G.handY - 12 - G.infoH;

      G.gridTop = Layout.top + 16;
      G.gridBot = G.infoY - 14;
      var gap = 10;
      var cw = Math.min(118, (Layout.w - 24 - (cols - 1) * gap) / cols);
      var ch = cw * 1.2;
      var maxH = (G.gridBot - G.gridTop - 28 - (rows - 1) * gap) / rows;
      if (ch > maxH) { ch = maxH; cw = ch / 1.2; }
      G.cw = cw; G.ch = ch; G.gap = gap;
      var gw = cols * cw + (cols - 1) * gap, gh = rows * ch + (rows - 1) * gap;
      G.gx0 = Layout.cx - gw / 2;
      G.gy0 = G.gridTop + 14 + Math.max(0, (G.gridBot - G.gridTop - 28 - gh) / 2);
      G.gw = gw; G.gh = gh;

      // the info band: deck pile left, last fight centre, the enemy commander right.
      // The pile sits high in the band, clear of the first hand slot under it.
      G.deckX = Layout.left + 4; G.deckW = 92; G.deckH = 116;
      G.deckY = G.infoY + 30;
      G.foeX = Layout.right - 12 - 150; G.foeW = 150; G.foeH = G.infoH;
      G.foeY = G.infoY;
      G.lastX = (G.deckX + G.deckW + G.foeX) / 2;
    }
    function cellX(c) { return G.gx0 + c * (G.cw + G.gap); }
    function cellY(r) { return G.gy0 + r * (G.ch + G.gap); }
    function cellAt(p) {
      for (var r = 0; r < rows; r++) for (var c = 0; c < cols; c++) {
        var x = cellX(c), y = cellY(r);
        if (p.x >= x - 6 && p.x <= x + G.cw + 6 && p.y >= y - 6 && p.y <= y + G.ch + 6) return { r: r, c: c };
      }
      return null;
    }
    function handX(i) { return G.handX0 + i * (HAND_W + HAND_GAP); }
    function handAt(p) {
      if (p.y < G.handY - 40 || p.y > G.handBottom + 10) return -1;
      for (var i = 0; i < handSize; i++) {
        if (hand[i] == null) continue;
        var x = handX(i);
        if (p.x >= x - 8 && p.x <= x + HAND_W + 8) return i;
      }
      return -1;
    }

    /* ===================================================================
       LIFECYCLE
       =================================================================== */
    function reset() {
      BAND = bandFor();
      Art.backdrop(BAND.scene);
      seed = ((CONFIG.level | 0) * 7919 + 12345) >>> 0;
      cols = Math.max(2, P.cols | 0); rows = Math.max(2, P.rows | 0);
      handSize = Math.max(2, P.handSize | 0);
      geometry();
      refills = [];
      buildGrid();
      buildDeck();
      computeReach();
      score = 0; streak = 0; bestStreak = 0;
      kills = 0; ties = 0; losses = 0; precise = 0; scouted = 0; trapsCleared = 0;
      selected = -1; drag = null; turn = null; ended = false; outcome = null; tAnim = 0;
      mood = "neutral"; lastFoe = null; lastWon = null;
      target = goalOf();
      HUD.setScoreNow(0);
      showCounts();
      Fx.reset();
      Music.play(CONFIG.level ? BAND.music : null);
    }
    /* The motor lays the frame out before any round exists (the intro, a
       turn of the device on the menu): nothing to place then — reset()
       builds the camp from Layout when the round starts. */
    function onResize() {
      if (!grid) return;
      geometry();
    }
    function showCounts() {
      var left = cardsLeft();
      HUD.setLeft(left, CONFIG.copy.cardsLabel, left <= 2 ? "warn" : "");
      HUD.setRight(foesLeft(), CONFIG.copy.foesLabel);
    }

    /* ===================================================================
       INPUT — pick a card, send it at a cell; or drag it there
       =================================================================== */
    function onDown(p) {
      if (ended || turn || State !== "playing") return;
      var i = handAt(p);
      if (i >= 0) {
        selected = i;
        drag = { i: i, x: p.x, y: p.y, sx: p.x, sy: p.y, moved: false };
        Sound.clip("pick", 0.45, 1 + i * 0.03);
        return;
      }
      var cell = cellAt(p);
      if (cell && selected >= 0 && hand[selected] != null) {
        if (isTarget(cell.r, cell.c)) attack(selected, cell.r, cell.c);
        else if (grid[cell.r][cell.c]) {
          Sound.clip("warn", 0.35, 1.2);
          Pop.show("alert", { word: "Out of reach" });
        }
        return;
      }
      selected = -1;
    }
    function onMove(p) {
      if (!drag) return;
      drag.x = p.x; drag.y = p.y;
      if (Math.abs(p.x - drag.sx) + Math.abs(p.y - drag.sy) > 14) drag.moved = true;
    }
    function onUp(p) {
      if (!drag) return;
      var d = drag; drag = null;
      if (ended || turn) return;
      if (!d.moved) return;                       // a tap: the card stays picked
      var cell = cellAt(p);
      if (cell && isTarget(cell.r, cell.c)) { attack(d.i, cell.r, cell.c); return; }
      if (cell && grid[cell.r][cell.c]) {
        Sound.clip("warn", 0.35, 1.2);
        Pop.show("alert", { word: "Out of reach" });
      }
    }

    /* ===================================================================
       THE FIGHT
       =================================================================== */

    /* The verdict, before anything moves: what happens to the attacker, to
       the defender, and what it pays. */
    function judge(a, foe) {
      var d = foe.rank;
      if (d === FLAG)  return { kind: "flag" };
      /* a scout REVEALS — a card already turned over leaves it nothing to
         do but fight, which a rank 2 mostly loses */
      if (a === SCOUT && !foe.known) return { kind: "scout" };
      if (d === TRAP)  return a === SAPPER ? { kind: "clear" } : { kind: "trap" };
      if (a === SPY && d === MARSHAL) return { kind: "win", margin: 1 };
      if (a > d)  return { kind: "win", margin: a - d };
      if (a < d)  return { kind: "lose" };
      return { kind: "tie" };
    }
    function mult() { return Math.min(STREAK_CAP, 1 + STREAK_STEP * Math.max(0, streak - 1)); }

    function attack(i, r, c) {
      var a = hand[i], foe = grid[r][c];
      if (a == null || !foe) return;
      selected = -1;
      turn = { state: "fly", t: 0, i: i, a: a, r: r, c: c, foe: foe,
               from: { x: handX(i) + HAND_W / 2, y: G.handY + HAND_H / 2 },
               verdict: judge(a, foe) };
      hand[i] = null;
      Sound.clip("place", 0.5, 1);
    }

    /* The verdict lands: the camp and the deck are updated here, once, at
       the moment of the clash — everything after it is the picture catching
       up. */
    function resolve(T) {
      var v = T.verdict, foe = T.foe, a = T.a, pts = 0, cx = cellX(T.c) + G.cw / 2, cy = cellY(T.r) + G.ch / 2;
      foe.known = true;
      lastFoe = foe.rank;

      if (v.kind === "scout") {
        scouted++;
        deck.push(a);
        pts = SCOUT_PAY;
        lastWon = null; mood = "neutral";
        Sound.clip("flip", 0.6, 1.3);
        Pop.show("alert", { word: Lang.t("Spotted") + ": " + Lang.t(rankName(foe.rank)) });
      } else if (v.kind === "flag") {
        pts = FLAG_PAY + ROUTED * (foesLeft() - 1);
        grid[T.r][T.c] = null;
        deck.push(a);
        kills++; streak++;
        lastWon = true; mood = "sad";
        Sound.clip("flag", 0.8, 1);
        Fx.flash(GOLD, 0.5, 2.5); Fx.shake(16, 0.4); Fx.freeze(0.1);
        Fx.ring(cx, cy, { from: 40, to: 700, color: GOLD, width: 10, life: 0.6 });
        Pop.show("ultra", { word: CONFIG.copy.flagTaken, sub: "+" + pts });
      } else if (v.kind === "clear") {
        pts = Math.round(TRAP_CLEAR * mult());
        grid[T.r][T.c] = null;
        deck.push(a);
        trapsCleared++; streak++;
        lastWon = true; mood = "sad";
        Sound.clip("win", 0.6, 1.1);
        Fx.burst(cx, cy, { color: [GOLD, "#ffffff"], count: 16, speed: 360, life: 0.5, grav: 500 });
        Pop.show("bonus", { word: "Trap cleared", sub: "+" + pts });
      } else if (v.kind === "trap") {
        losses++; streak = 0;
        lastWon = false; mood = "happy";
        Sound.clip("trap", 0.7, 1);
        Fx.flash(RED, 0.4, 2.2); Fx.shake(14, 0.35); Fx.freeze(0.06);
        Fx.burst(cx, cy, { color: [RED, "#3a0a0a"], count: 18, speed: 420, life: 0.5, grav: 600 });
        Pop.show("danger", { word: "Trap!" });
      } else if (v.kind === "win") {
        streak++;
        if (streak > bestStreak) bestStreak = streak;
        var tight = v.margin <= 1 ? 2 : v.margin === 2 ? 1 : 0.5;
        pts = Math.round(KILL * foe.rank * tight * mult());
        grid[T.r][T.c] = null;
        deck.push(a);
        kills++;
        if (v.margin <= 1) precise++;
        lastWon = true; mood = "sad";
        Sound.clip("win", 0.6, 0.9 + foe.rank * 0.03);
        Fx.burst(cx, cy, { color: [GOLD, BLUE, "#ffffff"], count: 14, speed: 380, life: 0.5, grav: 500 });
        Fx.shake(6, 0.2);
        if (v.margin <= 1) Pop.show("combo", { word: "Precise!", sub: "+" + pts });
        else if (v.margin >= 3) Pop.show("alert", { word: "Overkill" });
        if (streak >= 3 && v.margin <= 2) Pop.show("streak", { word: "x" + streak + Lang.t(" streak") });
      } else if (v.kind === "lose") {
        losses++; streak = 0;
        lastWon = false; mood = "happy";
        Sound.clip("lose", 0.6, 1);
        Fx.shake(10, 0.28); Fx.flash(RED, 0.25, 2.5);
        Pop.show("alert", { word: Lang.t(rankName(foe.rank)) + " " + Lang.t("holds") });
      } else {                                              // tie: both fall
        ties++; streak = 0;
        pts = TIE * foe.rank;
        grid[T.r][T.c] = null;
        lastWon = null; mood = "neutral";
        Sound.clip("tie", 0.6, 1);
        Fx.shake(8, 0.25);
        Fx.burst(cx, cy, { color: [BLUE, RED], count: 16, speed: 340, life: 0.5, grav: 500 });
        Pop.show("alert", { word: "Both fall" });
      }

      if (pts) {
        score += pts;
        HUD.setScore(score);
        HUD.punch(v.kind === "flag" ? GOLD : BLUE);
        Pop.text(cx, cy - G.ch * 0.6, "+" + pts, { color: GOLD, size: 22, life: 0.6, tier: 1 });
      }
      T.pts = pts;
      Sound.clip("clash", 0.5, 1);
      computeReach();
      showCounts();
    }

    /* After the pictures have caught up: a new card in the empty slot, and
       the two questions every turn ends on — is the camp empty, is the army. */
    function endTurn(T) {
      var v = T.verdict;
      refillHand(true);
      var left = cardsLeft();
      if (left <= 2 && left > 0) Sound.clip("warn", 0.4, 1);
      showCounts();
      turn = null;
      if (v.kind === "flag" || foesLeft() === 0) { finish(true); return; }
      if (left === 0) { finish(false); return; }
      if (!anyTarget()) { finish(true); }                 // nothing left to strike: the camp is taken
    }

    /* ===================================================================
       UPDATE — the turn's five beats
       =================================================================== */
    var FLY = 0.28, FLIP = 0.22, CLASH = 0.62, SETTLE = 0.36;

    function update(dt) {
      var i;
      tAnim += dt;
      for (i = refills.length - 1; i >= 0; i--) {
        refills[i].t += dt / 0.28;
        if (refills[i].t >= 1) refills.splice(i, 1);
      }
      if (!turn) return;
      var T = turn;
      T.t += dt;
      if (T.state === "fly" && T.t >= FLY) {
        T.state = "flip"; T.t = 0;
        Sound.clip("flip", 0.55, 1);
      } else if (T.state === "flip" && T.t >= FLIP) {
        T.state = "clash"; T.t = 0;
        resolve(T);
      } else if (T.state === "clash" && T.t >= CLASH) {
        T.state = "settle"; T.t = 0;
      } else if (T.state === "settle" && T.t >= SETTLE) {
        endTurn(T);
      }
    }

    /* ===================================================================
       RENDER
       =================================================================== */

    /* One card, drawn about its centre. `side` is blue (the army) or red (the
       camp); `down` is a face-down card; `lit` a target the player may strike. */
    function drawCard(rank, x, y, w, h, opt) {
      opt = opt || {};
      var side = opt.side || "blue", down = !!opt.down, lit = opt.lit || 0;
      var r = w * 0.11;
      ctx.save();
      ctx.translate(x, y);
      if (opt.rot) ctx.rotate(opt.rot);
      if (opt.scale) ctx.scale(opt.scale, opt.scale);
      if (opt.alpha != null) ctx.globalAlpha = opt.alpha;
      if (opt.flip != null) ctx.scale(Math.max(0.02, Math.abs(Math.cos(opt.flip * Math.PI))), 1);

      if (lit > 0) {
        roundRect(ctx, -w / 2 - 6, -h / 2 - 6, w + 12, h + 12, r + 6);
        ctx.fillStyle = rgba(GOLD, 0.18 + 0.22 * lit); ctx.fill();
      }
      roundRect(ctx, -w / 2, -h / 2, w, h, r);
      var g = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
      if (side === "blue") { g.addColorStop(0, down ? "#1d3f8f" : "#2a56b8"); g.addColorStop(1, down ? "#0c1a45" : "#112a66"); }
      else { g.addColorStop(0, down ? "#7a1b1b" : "#a32626"); g.addColorStop(1, down ? "#2c0707" : "#4a0d0d"); }
      ctx.fillStyle = g; ctx.fill();
      ctx.lineWidth = Math.max(2, w * 0.03);
      ctx.strokeStyle = lit > 0 ? rgba(GOLD, 0.7 + 0.3 * lit) : rgba("#d9a441", side === "blue" ? 0.85 : 0.7);
      ctx.stroke();
      // the inner frame
      roundRect(ctx, -w / 2 + w * 0.07, -h / 2 + w * 0.07, w - w * 0.14, h - w * 0.14, r * 0.6);
      ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,255,.14)"; ctx.stroke();

      var img;
      if (down) {
        img = art(CREST[side]);
        if (img) {
          var s = Math.min(w * 0.62 / img.naturalWidth, h * 0.6 / img.naturalHeight);
          ctx.globalAlpha *= 0.95;
          ctx.drawImage(img, -img.naturalWidth * s / 2, -img.naturalHeight * s / 2 - h * 0.04, img.naturalWidth * s, img.naturalHeight * s);
          ctx.globalAlpha = opt.alpha != null ? opt.alpha : 1;
        } else {
          ctx.fillStyle = "rgba(255,255,255,.12)";
          ctx.beginPath(); ctx.moveTo(0, -h * 0.28); ctx.lineTo(w * 0.28, 0); ctx.lineTo(0, h * 0.28); ctx.lineTo(-w * 0.28, 0); ctx.closePath(); ctx.fill();
        }
        ctx.fillStyle = rgba(INK, 0.8);
        ctx.font = font(h * 0.2, 900); ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("?", 0, h * 0.34);
      } else {
        var def = RANKS[rank];
        img = def.art ? art(def.art) : null;
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        if (img) {
          var s2 = Math.min(w * 0.7 / img.naturalWidth, h * 0.5 / img.naturalHeight);
          ctx.drawImage(img, -img.naturalWidth * s2 / 2, -img.naturalHeight * s2 / 2 - h * 0.06, img.naturalWidth * s2, img.naturalHeight * s2);
          if (rank <= 10) {
            ctx.fillStyle = INK; ctx.font = font(h * 0.17, 900);
            ctx.textAlign = "left"; ctx.textBaseline = "top";
            ctx.fillText(String(rank), -w / 2 + w * 0.1, -h / 2 + w * 0.09);
            ctx.textAlign = "center"; ctx.textBaseline = "middle";
          }
        } else {
          ctx.fillStyle = rank === TRAP ? RED : INK;
          ctx.font = font(h * 0.46, 900);
          ctx.fillText(String(rank), 0, -h * 0.08);
        }
        ctx.fillStyle = rgba(rank === TRAP || rank === FLAG ? GOLD : INK, 0.9);
        ctx.font = font(Math.max(11, h * 0.105), 800);
        ctx.fillText(upper(Lang.t(def.name)), 0, h * 0.36);
      }
      ctx.restore();
    }

    function drawPanel(x, y, w, h, r) {
      roundRect(ctx, x, y, w, h, r);
      ctx.fillStyle = "rgba(6,9,26,.58)"; ctx.fill();
      ctx.lineWidth = 2; ctx.strokeStyle = rgba(GOLD, 0.35); ctx.stroke();
    }

    function drawGrid() {
      var r, c, T = turn;
      drawPanel(G.gx0 - 14, G.gy0 - 14, G.gw + 28, G.gh + 28, 22);
      var pulse = 0.5 + 0.5 * Math.sin(tAnim * 4);
      for (r = 0; r < rows; r++) for (c = 0; c < cols; c++) {
        var x = cellX(c) + G.cw / 2, y = cellY(r) + G.ch / 2, cell = grid[r][c];
        if (!cell) {
          // an emptied cell: the path the army walks
          roundRect(ctx, cellX(c), cellY(r), G.cw, G.ch, G.cw * 0.11);
          ctx.fillStyle = reach[r + "," + c] ? rgba(GOLD, 0.07) : "rgba(255,255,255,.03)"; ctx.fill();
          ctx.setLineDash([7, 8]); ctx.lineWidth = 2;
          ctx.strokeStyle = reach[r + "," + c] ? rgba(GOLD, 0.28) : "rgba(255,255,255,.1)"; ctx.stroke();
          ctx.setLineDash([]);
          continue;
        }
        var busy = T && T.r === r && T.c === c;
        if (busy && (T.state === "flip" || T.state === "clash" || T.state === "settle")) continue;   // drawn by drawTurn
        var lit = isTarget(r, c) && !T ? (selected >= 0 || drag ? 0.6 + 0.4 * pulse : 0.25 + 0.25 * pulse) : 0;
        drawCard(cell.rank, x, y, G.cw, G.ch, { side: "red", down: !cell.known, lit: lit,
                 alpha: !isTarget(r, c) && !cell.known ? 0.82 : 1 });
      }
    }

    /* The turn's own drawing: the card in flight, the enemy turning over, the
       clash and the two cards' exits. */
    function drawTurn() {
      var T = turn;
      if (!T) return;
      var tx = cellX(T.c) + G.cw / 2, ty = cellY(T.r) + G.ch / 2;
      var v = T.verdict, k, ax, ay, sc;
      if (T.state === "fly") {
        k = ease(Math.min(1, T.t / FLY));
        ax = T.from.x + (tx - 34 - T.from.x) * k;
        ay = T.from.y + (ty + 22 - T.from.y) * k;
        sc = (HAND_W + (G.cw * 1.12 - HAND_W) * k) / HAND_W;
        drawCard(T.a, ax, ay - 40 * Math.sin(k * Math.PI), HAND_W, HAND_H, { scale: sc, rot: -0.12 * (1 - k) });
        return;
      }
      if (T.state === "flip") {
        k = Math.min(1, T.t / FLIP);
        drawCard(T.foe.rank, tx, ty, G.cw, G.ch, { side: "red", down: k < 0.5, flip: k, scale: 1 + 0.1 * Math.sin(k * Math.PI) });
        drawCard(T.a, tx - 34, ty + 22, G.cw * 1.12, G.ch * 1.12, { rot: -0.08 });
        return;
      }
      var won = v.kind === "win" || v.kind === "flag" || v.kind === "clear" || v.kind === "scout";
      var lost = v.kind === "lose" || v.kind === "trap";
      if (T.state === "clash") {
        k = Math.min(1, T.t / CLASH);
        var kick = Math.max(0, 1 - k * 4);
        // the enemy, face up, kicked back if it fell
        drawCard(T.foe.rank, tx + (won ? 10 * kick : 0), ty - (won ? 8 * kick : 0), G.cw, G.ch,
                 { side: "red", scale: 1.06, lit: lost ? 1 : 0 });
        // the army's card, in front, kicked back if it fell
        drawCard(T.a, tx - 34 - (lost ? 12 * kick : 0), ty + 22 + (lost ? 10 * kick : 0), G.cw * 1.12, G.ch * 1.12,
                 { rot: -0.08 + (lost ? 0.1 * kick : 0), scale: won ? 1.08 : 1 });
        return;
      }
      // settle: the loser fades, the winner leaves
      k = ease(Math.min(1, T.t / SETTLE));
      if (v.kind === "scout") {
        drawCard(T.foe.rank, tx, ty, G.cw, G.ch, { side: "red" });
        drawCard(T.a, tx - 34 + (G.deckX + G.deckW / 2 - (tx - 34)) * k, ty + 22 + (G.deckY + G.deckH / 2 - (ty + 22)) * k,
                 G.cw * 1.12, G.ch * 1.12, { scale: 1 - 0.4 * k, alpha: 1 - 0.6 * k });
      } else if (won) {
        drawCard(T.foe.rank, tx, ty + 30 * k, G.cw, G.ch, { side: "red", alpha: 1 - k, scale: 1 - 0.3 * k, rot: 0.3 * k });
        drawCard(T.a, tx - 34 + (G.deckX + G.deckW / 2 - (tx - 34)) * k, ty + 22 + (G.deckY + G.deckH / 2 - (ty + 22)) * k,
                 G.cw * 1.12, G.ch * 1.12, { scale: 1 - 0.4 * k, alpha: 1 - 0.5 * k });
      } else if (lost) {
        drawCard(T.foe.rank, tx, ty, G.cw, G.ch, { side: "red" });
        drawCard(T.a, tx - 34, ty + 22 + 40 * k, G.cw * 1.12, G.ch * 1.12, { alpha: 1 - k, scale: 1 - 0.35 * k, rot: -0.08 - 0.5 * k });
      } else {                                              // tie: both go
        drawCard(T.foe.rank, tx + 20 * k, ty - 20 * k, G.cw, G.ch, { side: "red", alpha: 1 - k, scale: 1 - 0.3 * k, rot: 0.4 * k });
        drawCard(T.a, tx - 34 - 20 * k, ty + 22 + 30 * k, G.cw * 1.12, G.ch * 1.12, { alpha: 1 - k, scale: 1 - 0.3 * k, rot: -0.5 * k });
      }
    }

    function drawHand() {
      var i, j, T = turn;
      for (i = 0; i < handSize; i++) {
        var x = handX(i) + HAND_W / 2, y = G.handY + HAND_H / 2;
        // the slot
        roundRect(ctx, handX(i), G.handY, HAND_W, HAND_H, HAND_W * 0.11);
        ctx.fillStyle = "rgba(255,255,255,.035)"; ctx.fill();
        ctx.setLineDash([8, 8]); ctx.lineWidth = 2; ctx.strokeStyle = "rgba(255,255,255,.14)"; ctx.stroke();
        ctx.setLineDash([]);
        if (hand[i] == null) continue;
        if (drag && drag.i === i && drag.moved) continue;   // drawn last, under the finger
        var arriving = null;
        for (j = 0; j < refills.length; j++) if (refills[j].slot === i) arriving = refills[j];
        if (arriving) {
          var k = ease(Math.min(1, arriving.t));
          var fx = G.deckX + G.deckW / 2, fy = G.deckY + G.deckH / 2;
          drawCard(hand[i], fx + (x - fx) * k, fy + (y - fy) * k, HAND_W, HAND_H, { down: k < 0.5, flip: k * 0.5 + 0.5, scale: 0.8 + 0.2 * k });
          continue;
        }
        var sel = selected === i && !T;
        drawCard(hand[i], x, sel ? y - 22 : y, HAND_W, HAND_H, { lit: sel ? 1 : 0, scale: sel ? 1.06 : 1 });
      }
      if (drag && drag.moved && hand[drag.i] != null) {
        drawCard(hand[drag.i], drag.x, drag.y - 30, HAND_W, HAND_H, { lit: 1, scale: 1.12, rot: (drag.x - (handX(drag.i) + HAND_W / 2)) / 1800 });
      }
    }

    function drawInfo() {
      // the deck pile, three backs deep, and its count
      var i, n = deck.length;
      for (i = Math.min(3, n) - 1; i >= 0; i--) {
        drawCard(0, G.deckX + G.deckW / 2 + i * 3, G.deckY + G.deckH / 2 - i * 4, G.deckW, G.deckH, { down: true, alpha: n ? 1 : 0.3 });
      }
      if (!n) {
        roundRect(ctx, G.deckX, G.deckY, G.deckW, G.deckH, G.deckW * 0.11);
        ctx.setLineDash([8, 8]); ctx.lineWidth = 2; ctx.strokeStyle = "rgba(255,255,255,.18)"; ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.font = font(20, 900); ctx.fillStyle = n <= 2 ? RED : rgba(INK, 0.85);
      ctx.fillText(upper(Lang.t("Deck")) + " " + n, G.deckX + G.deckW / 2, G.deckY - 16);

      // the enemy commander, reacting to the last fight
      var key = mood === "happy" ? "enemyHappy" : mood === "sad" ? "enemySad" : "enemyNeutral";
      var img = art(key);
      if (img) {
        var s = Math.min(G.foeW / img.naturalWidth, G.foeH / img.naturalHeight);
        var w = img.naturalWidth * s, h = img.naturalHeight * s;
        var bob = Math.sin(tAnim * 2.2) * 3;
        ctx.drawImage(img, G.foeX + (G.foeW - w) / 2, G.foeY + G.foeH - h + bob, w, h);
      }

      // the last card turned over, and how it went
      var cx = G.lastX, cy = G.infoY + G.infoH / 2 - 8;
      if (lastFoe != null) {
        drawCard(lastFoe, cx, cy - 4, 84, 100, { side: "red", alpha: 0.95 });
        var w2 = lastWon === true ? "Beaten" : lastWon === false ? "Holds" : lastFoe === FLAG ? "Taken" : "Spotted";
        ctx.font = font(18, 900); ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillStyle = lastWon === true ? GOLD : lastWon === false ? RED : rgba(INK, 0.8);
        ctx.fillText(upper(Lang.t(w2)), cx, cy + 66);
      } else {
        ctx.font = font(18, 800); ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillStyle = rgba(INK, 0.55);
        ctx.fillText(upper(Lang.t("Pick a card")), cx, cy - 12);
        ctx.fillText(upper(Lang.t("Strike the front row")), cx, cy + 16);
      }
      // the streak, while there is one
      if (streak >= 2) {
        ctx.font = font(18, 900); ctx.fillStyle = GOLD; ctx.textAlign = "center";
        ctx.fillText("x" + streak + " " + upper(Lang.t("streak")), cx, G.infoY + 14);
      }
    }

    function render() {
      /* The camp is the painted scene (CONFIG.sceneArt), a CSS layer under the
         canvas the frame pipeline has already wiped. The gradient is the
         fallback for a build with no artwork on disk. */
      if (!Art.scene()) {
        var g = ctx.createLinearGradient(0, 0, 0, view.h);
        g.addColorStop(0, "#132048"); g.addColorStop(1, "#070a18");
        ctx.fillStyle = g; ctx.fillRect(0, 0, view.w, view.h);
      }
      drawGrid();
      drawInfo();
      drawHand();
      drawTurn();
    }

    /* ===================================================================
       THE END OF A BATTLE
       =================================================================== */
    function finish(won) {
      if (ended) return;
      ended = true; outcome = won; turn = null; drag = null; selected = -1;
      var bonus = won ? SURVIVOR * cardsLeft() : 0;
      score += bonus;
      HUD.setScore(score);
      var best = Math.max(score, Store.get("bestScore", 0));
      var stars = score >= target * 2.2 ? 3 : score >= target * 1.5 ? 2 : score >= target ? 1 : 0;
      if (won) {
        Sound.clip("victory", 0.8, 1);
        Fx.flash(GOLD, 0.4, 2);
        Pop.show("perfect", { word: CONFIG.copy.victory, sub: bonus ? "+" + bonus : "" });
      } else {
        Sound.clip("defeat", 0.8, 1);
        Fx.flash(RED, 0.4, 1.6);
        Pop.show("danger", { word: CONFIG.copy.gameOver });
      }
      endRound({
        title: won ? CONFIG.copy.victory : CONFIG.copy.gameOver,
        variant: won && stars === 3 ? "win" : "",
        score: score,
        stars: stars,
        rows: [
          { label: "Foes beaten",  value: kills },
          { label: "Precise hits", value: precise, grade: "accent" },
          { label: "Best streak",  value: "x" + Math.max(1, bestStreak) },
          { label: "Best score",   value: best, grade: "gold" }
        ],
        track: { score: score, kills: kills, losses: losses, ties: ties, scouted: scouted, traps: trapsCleared, won: won }
      });
    }

    /* The web target's level layer: `applyLevel` hands the climb's `d` before
       the round (the objective comes from it), and `levelWon` ends the round
       through the game's own result on the third star, so the end screen
       keeps these stat rows. Ignored by the playable. */
    function levelWon() { finish(true); }
    /* A CAP over what the score bands pay, never a promotion: a battle the
       army LOST is worth one star however many points it piled up on the
       way down — the bench showed a pilot throwing its biggest cards blind
       losing every level-30 camp and still scoring two stars' worth. */
    function levelStars(stars) { return outcome === false ? Math.min(stars, 1) : stars; }

    return { reset: reset, update: update, render: render,
             onDown: onDown, onMove: onMove, onUp: onUp, onResize: onResize,
             applyLevel: applyLevel, levelWon: levelWon, levelStars: levelStars };
  })();
